import type { Cell } from '../types'
import { cellKey } from '../state/editor'
import type { GridRegion } from './dataRegion'
import { significantDigits, textToNumber } from './spreadsheetNumber'
import { parseFilterRange } from './filter'

export type CompareSide='left'|'right'
export type CompareRow={key:string;label:string;row:number;count:number}
export type CompareResult={
  onlyLeft:CompareRow[]
  onlyRight:CompareRow[]
  both:number
  /** 한쪽에 같은 키가 두 번 이상 나온 것. 대사에서는 이것 자체가 발견이다. */
  duplicated:Array<{side:CompareSide;key:string;label:string;count:number}>
  /** 키 칸이 비어 있어 견줄 수 없던 행. 조용히 빼면 수가 맞지 않는다. */
  blank:{left:number;right:number}
}

/**
 * 두 목록을 견주는 열쇠를 만든다.
 *
 * 은행에서 받은 내역은 금액이 "1,234" 처럼 글자로 오고 장부에는 숫자로
 * 적혀 있다. 사람 눈에는 같은 값인데 글자 그대로 견주면 하나도 맞지 않는다.
 * 숫자로 읽히는 것은 숫자로 견준다 — 세는 규칙은 다른 곳과 같은 것을 쓴다.
 *
 * 앞뒤 빈칸은 버리고 영문 대소문자는 가리지 않는다. 다른 곳에서 옮겨 적힌
 * 이름은 그 정도로 흔들리고, 그 흔들림까지 "없는 항목" 으로 세면 대사표가
 * 쓸모없어진다.
 */
/**
 * 수로 바꾸면 안 되는 것을 가려낸다.
 *
 *   "007"    앞의 0은 번호를 뜻한다. 수로 보면 7 과 같아져,
 *            007번 전표와 7번 전표가 한 항목이 된다.
 *   20자리   배정밀도가 정확히 담는 것은 열다섯 자리까지다. 서로 다른
 *            계좌번호 둘이 같은 키가 되어 "맞았다" 고 나온다.
 *
 * 대사에서 틀리게 맞았다고 하는 것은 안 맞았다고 하는 것보다 나쁘다.
 * 안 맞으면 사람이 들여다보지만, 맞았다고 하면 거기서 끝난다.
 *
 * 쉼표나 통화 기호가 붙은 금액은 여기서 걸리지 않는다. 그것은 번호가 아니라
 * 금액이고, "1,000" 과 1000 은 같아야 한다.
 */
function looksLikeIdentifier(text:string){
  const digits=text.replace(/^[+-]/,'')
  if(!/^\d+(\.\d+)?$/.test(digits))return false
  if(/^0\d/.test(digits))return true
  return significantDigits(digits)>15
}

export function compareKey(value:unknown):string|undefined{
  if(value==null)return undefined
  if(typeof value==='boolean')return value?'TRUE':'FALSE'
  if(typeof value==='number')return Number.isFinite(value)?String(value):undefined
  if(typeof value!=='string')return undefined
  const text=value.trim()
  if(text==='')return undefined
  if(looksLikeIdentifier(text))return text.toLowerCase()
  const numeric=Number(text)
  if(Number.isFinite(numeric))return String(numeric)
  const loose=textToNumber(text)
  if(loose!==undefined)return String(loose)
  return text.toLowerCase()
}

function readSide(cells:Map<string,Cell>,region:GridRegion,keyColumn:number,headerRows:number){
  const byKey=new Map<string,CompareRow>()
  let blank=0
  for(let row=region.startRow+headerRows;row<=region.endRow;row+=1){
    const cell=cells.get(cellKey(row,keyColumn))
    const key=compareKey(cell?.value)
    if(key===undefined){
      // 행 전체가 비어 있으면 목록의 끝일 뿐이다. 키만 비어 있는 행은 셈한다.
      if(rowHasAnything(cells,region,row))blank+=1
      continue
    }
    const existing=byKey.get(key)
    if(existing){existing.count+=1;continue}
    byKey.set(key,{key,label:displayText(cell),row,count:1})
  }
  return {byKey,blank}
}

function rowHasAnything(cells:Map<string,Cell>,region:GridRegion,row:number){
  for(let column=region.startColumn;column<=region.endColumn;column+=1){
    const cell=cells.get(cellKey(row,column))
    if(cell?.formula||(cell?.value!=null&&cell.value!==''))return true
  }
  return false
}

const displayText=(cell?:Cell)=>cell?.value==null?'':typeof cell.value==='string'?cell.value:String(cell.value)

/**
 * 두 목록을 키 열로 견준다. 어느 쪽에만 있는지, 양쪽에 있는지, 한쪽에서
 * 거듭 나오는지를 낸다.
 */
export function compareLists(
  left:{cells:Map<string,Cell>;region:GridRegion;keyColumn:number;headerRows:number},
  right:{cells:Map<string,Cell>;region:GridRegion;keyColumn:number;headerRows:number},
):CompareResult{
  const a=readSide(left.cells,left.region,left.keyColumn,left.headerRows)
  const b=readSide(right.cells,right.region,right.keyColumn,right.headerRows)
  const onlyLeft:CompareRow[]=[],onlyRight:CompareRow[]=[]
  let both=0
  for(const row of a.byKey.values()){if(b.byKey.has(row.key))both+=1;else onlyLeft.push(row)}
  for(const row of b.byKey.values())if(!a.byKey.has(row.key))onlyRight.push(row)
  const duplicated=[
    ...[...a.byKey.values()].filter(row=>row.count>1).map(row=>({side:'left' as const,key:row.key,label:row.label,count:row.count})),
    ...[...b.byKey.values()].filter(row=>row.count>1).map(row=>({side:'right' as const,key:row.key,label:row.label,count:row.count})),
  ]
  return {onlyLeft,onlyRight,both,duplicated,blank:{left:a.blank,right:b.blank}}
}

/**
 * "장부!A1:C100" 을 시트 이름과 범위로 나눈다. 느낌표가 없으면 시트 이름이
 * 없는 것으로 보고 undefined 를 낸다 — 부르는 쪽이 지금 시트를 넣는다.
 *
 * 시트 이름에도 느낌표가 들어갈 수 있으므로 **마지막** 느낌표에서 자른다.
 * 앞에서 자르면 "1분기!실적" 이라는 이름의 시트를 영영 못 고른다.
 */
export function splitSheetRange(value:string):{sheetName?:string;region:GridRegion}|undefined{
  const text=value.trim()
  if(text==='')return undefined
  const split=text.lastIndexOf('!')
  const region=parseFilterRange(text.slice(split+1))
  if(!region)return undefined
  if(split<0)return {region}
  // 이름에 빈칸이 있으면 따옴표로 감싸는 것이 스프레드시트의 버릇이다.
  const sheetName=text.slice(0,split).trim().replace(/^'(.*)'$/,'$1')
  return sheetName===''?undefined:{sheetName,region}
}
import { describe,expect,it } from 'vitest'
import { cellKey } from '../state/editor'
import type { Cell } from '../types'
import { compareKey, compareLists, splitSheetRange } from './compareLists'

const cell=(row:number,column:number,value?:unknown):Cell=>({sheet_id:'s',row,column,updated_at:'',...(value===undefined?{}:{value})})
const side=(values:unknown[],headerRows=0)=>({
  cells:new Map(values.map((value,index)=>[cellKey(index+1,1),cell(index+1,1,value)])),
  region:{startRow:1,startColumn:1,endRow:values.length,endColumn:1},
  keyColumn:1,headerRows,
})

describe('compareKey',()=>{
  it('reads a number written as text as the same key',()=>{
    // 은행 내역은 "1,234" 로 오고 장부에는 1234 로 적혀 있다. 글자 그대로
    // 견주면 하나도 맞지 않는다.
    expect(compareKey('1,234')).toBe(compareKey(1234))
    expect(compareKey('₩5,000')).toBe(compareKey(5000))
    expect(compareKey(' 300 ')).toBe(compareKey(300))
  })
  it('ignores surrounding spaces and letter case',()=>{
    expect(compareKey(' ABC ')).toBe(compareKey('abc'))
  })
  it('has no key for a blank cell',()=>{
    expect(compareKey('')).toBeUndefined()
    expect(compareKey(null)).toBeUndefined()
    expect(compareKey('   ')).toBeUndefined()
  })
  it('does not force text that is not a number',()=>{
    expect(compareKey('1,2,3')).toBe('1,2,3')
  })
})

describe('compareLists',()=>{
  it('says what is on one side only',()=>{
    const result=compareLists(side(['가','나','다']),side(['나','다','라']))
    expect(result.onlyLeft.map(row=>row.label)).toEqual(['가'])
    expect(result.onlyRight.map(row=>row.label)).toEqual(['라'])
    expect(result.both).toBe(2)
  })

  it('matches a bank list written as text against a ledger of numbers',()=>{
    const result=compareLists(side(['1,000','2,000','3,000']),side([1000,2000,4000]))
    expect(result.both).toBe(2)
    expect(result.onlyLeft.map(row=>row.label)).toEqual(['3,000'])
    expect(result.onlyRight.map(row=>row.label)).toEqual(['4000'])
  })

  it('reports a key that appears twice instead of hiding it',()=>{
    // 대사에서 같은 번호가 두 번 나오는 것은 발견이지 잡음이 아니다.
    const result=compareLists(side(['가','가','나']),side(['가','나']))
    expect(result.duplicated).toEqual([{side:'left',key:'가',label:'가',count:2}])
    expect(result.both).toBe(2)
  })

  it('counts rows whose key cell is empty rather than dropping them',()=>{
    // 조용히 빼면 "다 맞았다" 는 대사표가 나오고 수는 맞지 않는다.
    const cells=new Map([[cellKey(1,1),cell(1,1,'가')],[cellKey(2,1),cell(2,1,'')],[cellKey(2,2),cell(2,2,'금액만 있음')]])
    const left={cells,region:{startRow:1,startColumn:1,endRow:2,endColumn:2},keyColumn:1,headerRows:0}
    expect(compareLists(left,side(['가'])).blank.left).toBe(1)
  })

  it('skips the header row when told to',()=>{
    const result=compareLists(side(['이름','가'],1),side(['이름','가'],1))
    expect(result.both).toBe(1)
    expect(result.onlyLeft).toEqual([])
  })
})

describe('splitSheetRange',()=>{
  it('splits a sheet name from a range',()=>{
    expect(splitSheetRange('장부!A1:C100')).toEqual({sheetName:'장부',region:{startRow:1,startColumn:1,endRow:100,endColumn:3}})
  })
  it('splits at the last mark so a name may contain one',()=>{
    // "1분기!실적" 이라는 이름의 시트를 앞에서 자르면 영영 못 고른다.
    expect(splitSheetRange('1분기!실적!A1:B2')?.sheetName).toBe('1분기!실적')
  })
  it('unwraps the quotes a name with spaces gets',()=>{
    expect(splitSheetRange("'상반기 장부'!A1:B2")?.sheetName).toBe('상반기 장부')
  })
  it('leaves the sheet unnamed when there is no mark',()=>{
    expect(splitSheetRange('A1:B2')).toEqual({region:{startRow:1,startColumn:1,endRow:2,endColumn:2}})
  })
  it('refuses what is not a range',()=>{
    expect(splitSheetRange('장부!')).toBeUndefined()
    expect(splitSheetRange('장부!A1')).toBeUndefined()
    expect(splitSheetRange('')).toBeUndefined()
    expect(splitSheetRange('!A1:B2')).toBeUndefined()
  })
})

describe('keys that must not be read as numbers',()=>{
  // 대사에서 틀리게 "맞았다" 고 하는 것은 "안 맞았다" 고 하는 것보다 나쁘다.
  // 안 맞으면 사람이 들여다보지만, 맞았다고 하면 거기서 끝난다.
  it('keeps a leading zero apart from the bare number',()=>{
    expect(compareKey('007')).not.toBe(compareKey('7'))
    expect(compareKey('007')).toBe('007')
  })
  it('keeps two long account numbers apart',()=>{
    // 배정밀도로 읽으면 뒤가 뭉개져 둘이 같은 키가 된다.
    expect(compareKey('12345678901234567890')).not.toBe(compareKey('12345678901234567891'))
  })
  it('still matches amounts written with separators',()=>{
    expect(compareKey('1,000')).toBe(compareKey(1000))
    expect(compareKey('0')).toBe(compareKey(0))
    expect(compareKey('0.5')).toBe(compareKey(0.5))
  })
  it('finds the difference two long numbers really have',()=>{
    const result=compareLists(side(['12345678901234567890']),side(['12345678901234567891']))
    expect(result.both).toBe(0)
    expect(result.onlyLeft).toHaveLength(1)
    expect(result.onlyRight).toHaveLength(1)
  })
})
/**
 * 값이 숫자로 셈에 들어가는지, 들어간다면 얼마인지 정한다.
 *
 * 이 규칙은 서버의 수식 엔진이 정한다. 화면이 다르게 세면 =SUM(A1:A100) 이
 * 내는 값과 상태 줄에 보이는 합계가 달라지고, 사람은 어느 쪽을 믿어야 할지
 * 알 수 없다. 실제로 그런 일이 있었다 — 선택 요약과 열 통계와 엔진이 셋 다
 * 달랐다.
 *
 *   "2000"    셈한다        엔진도 그렇다
 *   " 300 "   셈한다        앞뒤 빈칸은 버린다
 *   TRUE      1 로 센다     엔진도 그렇다
 *   "1,234"   세지 않는다   쉼표가 붙으면 엔진은 글자로 본다
 *   "50%"     세지 않는다
 *   "1234원"  세지 않는다
 *
 * 쉼표가 붙은 것을 세지 않는 것이 야박해 보이지만, 세는 쪽이 더 나쁘다.
 * 화면에는 더해지는데 수식에서는 빠지므로 두 숫자가 어긋난 채로 남는다.
 * 그런 칸은 세는 대신 찾아서 알려 주고 숫자로 바꿔 주는 편이 낫다.
 */
/** 스프레드시트가 숫자라고 부르는 글자. 서버의 internal/formula/evaluator.go
 *  decimalText 와 같은 자다. testdata/numeric-text.json 이 둘을 붙들어 둔다. */
const DECIMAL_TEXT=/^[+-]?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/

export function spreadsheetNumber(value:unknown):number|undefined{
  if(typeof value==='number')return Number.isFinite(value)?value:undefined
  if(typeof value==='boolean')return value?1:0
  if(typeof value==='string'){
    const text=value.trim()
    // Number() 는 스프레드시트보다 넓다. `0x1F` 를 31 로, `0b101` 을 5 로 읽는다.
    // 엔진은 그것을 세지 않으므로, 그대로 두면 상태 줄 합계에만 들어가고
    // =SUM 에는 빠진 채 두 숫자가 어긋난다. 실제로 그랬다.
    if(!DECIMAL_TEXT.test(text))return undefined
    const parsed=Number(text)
    return Number.isFinite(parsed)?parsed:undefined
  }
  return undefined
}

/**
 * 숫자처럼 보이는데 글자로 담긴 칸인지 본다.
 *
 * 다른 곳에서 붙여 넣으면 "1,234" 나 "1,234원" 처럼 들어온다. 사람 눈에는
 * 숫자인데 =SUM 은 조용히 빼고 셈한다. 합계가 작게 나오는데 무엇이 빠졌는지는
 * 아무 데도 적히지 않는다.
 */
export function looksLikeNumberStoredAsText(value:unknown):boolean{
  if(typeof value!=='string')return false
  const text=value.trim()
  if(text==='')return false
  // 이미 셈에 들어가는 것은 고칠 것이 없다.
  if(spreadsheetNumber(text)!==undefined)return false
  return textToNumber(text)!==undefined
}

/**
 * 글자로 담긴 숫자를 숫자로 바꾼다. 바꿀 수 없으면 undefined 다.
 *
 * 쉼표, 원·달러 기호, 뒤에 붙은 단위, 괄호 음수, 백분율을 받는다. 괄호는
 * 회계에서 음수를 적는 꼴이고, 백분율은 100 으로 나눈다 — 화면에 보이던 것과
 * 셈하는 값이 같아야 한다.
 */
/**
 * 글자 하나를 숫자와 표시 형식으로 뜯는다.
 *
 * 같은 글자가 이 앱에 들어오는 길은 셋이다 — 붙여넣기, 데이터 정리, 그리고
 * 셀에 직접 치는 것. 셋이 따로 뜯으면 같은 "₩5,000" 이 어떻게 들어왔는지에
 * 따라 다른 값이나 다른 서식으로 저장된다. 사람에게는 같은 자료인데 파일에서는
 * 다르다. 그래서 뜯는 일은 여기 한 군데서만 한다.
 *
 * 뜯은 것은 반드시 원래 글자로 다시 그려져야 한다. 기호와 단위에 붙어 있던
 * 빈칸까지 서식 안에 담는 것은 그 때문이다 — `5000 USD` 를 `5000USD` 로
 * 되돌리면 사람이 옮긴 표와 다른 것을 보게 된다.
 */
export type NumberText={value:number;format?:string}

const CURRENCY_SIGN=/^([₩$€¥£¢])(\s*)/
const UNIT_SUFFIX=/(\s*)(원|달러|USD|KRW|won)$/i
const GROUPED_INTEGER=/^\d{1,3}(,\d{3})+$/
const PLAIN_INTEGER=/^\d+$/
/**
 * 앞의 0 이 자리가 아니라 번호를 뜻하는 평문 정수. `0`·`0.5`·`-0`·`007.5` 의
 * 0 은 자리이고, `00123`·`007` 처럼 0 뒤에 숫자가 더 오면서 소수점이 없을
 * 때만 번호다. 자릿점이나 통화 기호가 붙은 것은 번호가 아니라 금액이므로
 * 여기서 걸리지 않는다. 서버의 delimited.HasSignificantLeadingZero 와 같은
 * 자다.
 */
const LEADING_ZERO_NUMBER=/^[+-]?0\d+$/

export function decomposeNumberText(value:string):NumberText|undefined{
  let text=value.trim()
  // 마흔 자를 넘는 것은 금액이 아니라 문장이다.
  if(text===''||text.length>40)return undefined
  // 우편번호·사번의 앞자리 0 은 숫자로 바꾸는 순간 사라지고 되돌릴 길이 없다.
  // 열여섯 자리 넘는 번호를 아래에서 놓아주는 것과 같은 까닭이다. 파일로
  // 들어오는 문(internal/delimited 의 Number — 업로드 가져오기와 IMPORTDATA)이
  // 이미 그렇게 하므로, 같은 표를 CSV 로 올리느냐 복사해 붙이느냐에 따라
  // 다른 값이 남지 않으려면 여기서도 글자로 두어야 한다.
  // testdata/incoming-number.json 이 두 문을 붙들어 둔다.
  //
  // 칸에 직접 쳐 넣는 것은 다른 문이다 — cellEntry 의 parseTypedCellValue 는
  // 여기에 닿기 전에 위의 spreadsheetNumber 로 읽으므로 사람이 친 `00123` 은
  // 예전대로 123 이다. 파일은 되돌릴 길이 없지만 친 사람은 다시 칠 수 있다.
  if(LEADING_ZERO_NUMBER.test(text))return undefined
  let negative=false
  const parenthesized=/^\(.*\)$/.test(text)
  if(parenthesized){negative=true;text=text.slice(1,-1).trim()}
  const leading=(prefix:string)=>{
    if(!text.startsWith(prefix))return false
    text=text.slice(1).trim();return true
  }
  if(leading('-'))negative=!negative
  else leading('+')
  let currency='',currencyGap=''
  const sign=text.match(CURRENCY_SIGN)
  if(sign){currency=sign[1];currencyGap=sign[2];text=text.slice(sign[0].length)}
  // `$-5` 처럼 기호 뒤에 부호가 오는 표기도 있다.
  if(currency!==''){if(leading('-'))negative=!negative;else leading('+')}
  let percent=false
  if(text.endsWith('%')){percent=true;text=text.slice(0,-1).trim()}
  let unit='',unitGap=''
  const suffix=text.match(UNIT_SUFFIX)
  if(suffix){unitGap=suffix[1];unit=suffix[2];text=text.slice(0,text.length-suffix[0].length)}
  // 백분율에 단위를 붙인 것은 뜻이 없다. `5%원` 을 억지로 읽지 않는다.
  if(percent&&unit!=='')return undefined
  const [integer,fraction,...rest]=text.trim().split('.')
  if(rest.length>0)return undefined
  if(fraction!==undefined&&!PLAIN_INTEGER.test(fraction))return undefined
  // 쉼표는 세 자리마다 하나여야 한다. 아무 데나 찍힌 `1,2` 는 소수점으로
  // 쉼표를 쓰는 표기이지 자릿수 구분이 아니다.
  const grouped=GROUPED_INTEGER.test(integer)
  if(!grouped&&!PLAIN_INTEGER.test(integer))return undefined
  const digits=integer.replace(/,/g,'')+(fraction===undefined?'':'.'+fraction)
  // 배정밀도가 정확히 담는 것은 열다섯 자리까지다. 그보다 긴 것은 계좌번호나
  // 전표번호이지 금액이 아니다. 숫자로 바꾸면 뒤가 뭉개져, 적은 사람이 보던
  // 것과 다른 값이 칸에 들어간다. 글자로 두면 적어도 그대로 남는다.
  if(significantDigits(digits)>15)return undefined
  const parsed=Number(digits)
  if(!Number.isFinite(parsed))return undefined
  const value_=(negative?-parsed:parsed)/(percent?100:1)
  // 서식이 필요 없는 평범한 숫자에는 서식을 붙이지 않는다. 붙이면 칸마다
  // 쓸모없는 스타일이 하나씩 생긴다.
  if(!grouped&&currency===''&&unit===''&&!percent&&!parenthesized)return {value:value_}
  return {value:value_,format:numberTextFormat({grouped,currency,currencyGap,unit,unitGap,percent,parenthesized,decimals:fraction?.length??0})}
}

function numberTextFormat({grouped,currency,currencyGap,unit,unitGap,percent,parenthesized,decimals}:{
  grouped:boolean;currency:string;currencyGap:string;unit:string;unitGap:string;percent:boolean;parenthesized:boolean;decimals:number}){
  // 기호는 따옴표로 묶는다. 엑셀 서식 말에서 따옴표 안은 언제나 그대로 적는
  // 글자이므로, `$` 처럼 다른 뜻으로 읽힐 수 있는 기호도 안전하다. 빈칸도
  // 따옴표 안에 넣어야 그려질 때 살아남는다.
name: ci

on:
  push:
    branches: [main]
  pull_request:

jobs:
  commit-identity:
    runs-on: ubuntu-latest
    steps:
      - uses: actions/checkout@v4
        with:
          fetch-depth: 0
      - name: Enforce hkjang commit identity
        run: ./scripts/check-commit-identities.sh HEAD
      - name: Check release docs agree
        run: ./scripts/check-release-docs.sh

  test:
    runs-on: ubuntu-latest
    services:
      postgres:
        image: postgres:17-alpine
        env:
          POSTGRES_DB: kanpic_test
          POSTGRES_USER: kanpic
          POSTGRES_PASSWORD: kanpic-test
        ports: ["5432:5432"]
        options: >-
          --health-cmd "pg_isready -U kanpic -d kanpic_test"
          --health-interval 2s
          --health-timeout 3s
          --health-retries 15
    steps:
      - uses: actions/checkout@v4
      - uses: actions/setup-go@v5
        with: { go-version: "1.26.x", cache: true }
      - uses: actions/setup-node@v4
        with: { node-version: "24", cache: npm, cache-dependency-path: web/package-lock.json }
      # 서식이 어긋난 파일은 diff 를 시끄럽게 만들어, 정작 무엇이 바뀌었는지
      # 가린다. 사람이 알아채기 전에 여기서 먼저 잡는다.
      - name: Check Go files are gofmt clean
        run: |
          unformatted=$(gofmt -l ./cmd ./internal ./pkg)
          if [ -n "$unformatted" ]; then
            echo "gofmt 가 필요한 파일:"
            echo "$unformatted"
            gofmt -d ./cmd ./internal ./pkg
            exit 1
          fi
      - run: go test ./...
      - run: npm ci && npm test && npm run build
        working-directory: web
      - run: go test -tags=integration ./internal/...
        env:
          POSTGRES_DSN: postgres://kanpic:kanpic-test@localhost:5432/kanpic_test?sslmode=disable
      - name: Install Playwright Chromium
        run: node ./node_modules/@playwright/test/cli.js install --with-deps chromium
        working-directory: web
      - name: Run browser E2E against kanpic server
        env:
          POSTGRES_DSN: postgres://kanpic:kanpic-test@localhost:5432/kanpic_test?sslmode=disable
          KANPIC_E2E_BASE_URL: http://127.0.0.1:8080
        run: |
          go run ./cmd/api >/tmp/kanpic-e2e-server.log 2>&1 &
          server_pid=$!
          cleanup() {
            kill "$server_pid" 2>/dev/null || true
          }
          trap cleanup EXIT
          for attempt in $(seq 1 30); do
            if curl --fail --silent http://127.0.0.1:8080/healthz >/dev/null; then
              break
            fi
            sleep 1
          done
          curl --fail --silent http://127.0.0.1:8080/healthz >/dev/null || {
            cat /tmp/kanpic-e2e-server.log
            exit 1
          }
          cd web
          npm run test:e2e

import type { Cell } from '../types'
import { cellKey } from '../state/editor'
import type { GridRegion } from './dataRegion'
import { significantDigits, textToNumber } from './spreadsheetNumber'
import { parseFilterRange } from './filter'

export type CompareSide='left'|'right'
export type CompareRow={key:string;label:string;row:number;count:number}
export type CompareResult={
  onlyLeft:CompareRow[]
  onlyRight:CompareRow[]
  both:number
  /** 한쪽에 같은 키가 두 번 이상 나온 것. 대사에서는 이것 자체가 발견이다. */
  duplicated:Array<{side:CompareSide;key:string;label:string;count:number}>
  /** 키 칸이 비어 있어 견줄 수 없던 행. 조용히 빼면 수가 맞지 않는다. */
  blank:{left:number;right:number}
}

/**
 * 두 목록을 견주는 열쇠를 만든다.
 *
 * 은행에서 받은 내역은 금액이 "1,234" 처럼 글자로 오고 장부에는 숫자로
 * 적혀 있다. 사람 눈에는 같은 값인데 글자 그대로 견주면 하나도 맞지 않는다.
 * 숫자로 읽히는 것은 숫자로 견준다 — 세는 규칙은 다른 곳과 같은 것을 쓴다.
 *
 * 앞뒤 빈칸은 버리고 영문 대소문자는 가리지 않는다. 다른 곳에서 옮겨 적힌
 * 이름은 그 정도로 흔들리고, 그 흔들림까지 "없는 항목" 으로 세면 대사표가
 * 쓸모없어진다.
 */
/**
 * 수로 바꾸면 안 되는 것을 가려낸다.
 *
 *   "007"    앞의 0은 번호를 뜻한다. 수로 보면 7 과 같아져,
 *            007번 전표와 7번 전표가 한 항목이 된다.
 *   20자리   배정밀도가 정확히 담는 것은 열다섯 자리까지다. 서로 다른
 *            계좌번호 둘이 같은 키가 되어 "맞았다" 고 나온다.
 *
 * 대사에서 틀리게 맞았다고 하는 것은 안 맞았다고 하는 것보다 나쁘다.
 * 안 맞으면 사람이 들여다보지만, 맞았다고 하면 거기서 끝난다.
 *
 * 쉼표나 통화 기호가 붙은 금액은 여기서 걸리지 않는다. 그것은 번호가 아니라
 * 금액이고, "1,000" 과 1000 은 같아야 한다.
 */
function looksLikeIdentifier(text:string){
  const digits=text.replace(/^[+-]/,'')
  if(!/^\d+(\.\d+)?$/.test(digits))return false
  if(/^0\d/.test(digits))return true
  return significantDigits(digits)>15
}

export function compareKey(value:unknown):string|undefined{
  if(value==null)return undefined
  if(typeof value==='boolean')return value?'TRUE':'FALSE'
  if(typeof value==='number')return Number.isFinite(value)?String(value):undefined
  if(typeof value!=='string')return undefined
  const text=value.trim()
  if(text==='')return undefined
  if(looksLikeIdentifier(text))return text.toLowerCase()
  const numeric=Number(text)
  if(Number.isFinite(numeric))return String(numeric)
  const loose=textToNumber(text)
  if(loose!==undefined)return String(loose)
  return text.toLowerCase()
}

function readSide(cells:Map<string,Cell>,region:GridRegion,keyColumn:number,headerRows:number){
  const byKey=new Map<string,CompareRow>()
  let blank=0
  for(let row=region.startRow+headerRows;row<=region.endRow;row+=1){
    const cell=cells.get(cellKey(row,keyColumn))
    const key=compareKey(cell?.value)
    if(key===undefined){
      // 행 전체가 비어 있으면 목록의 끝일 뿐이다. 키만 비어 있는 행은 셈한다.
      if(rowHasAnything(cells,region,row))blank+=1
      continue
    }
    const existing=byKey.get(key)
    if(existing){existing.count+=1;continue}
    byKey.set(key,{key,label:displayText(cell),row,count:1})
  }
  return {byKey,blank}
}

function rowHasAnything(cells:Map<string,Cell>,region:GridRegion,row:number){
  for(let column=region.startColumn;column<=region.endColumn;column+=1){
    const cell=cells.get(cellKey(row,column))
    if(cell?.formula||(cell?.value!=null&&cell.value!==''))return true
  }
  return false
}

const displayText=(cell?:Cell)=>cell?.value==null?'':typeof cell.value==='string'?cell.value:String(cell.value)

/**
 * 두 목록을 키 열로 견준다. 어느 쪽에만 있는지, 양쪽에 있는지, 한쪽에서
 * 거듭 나오는지를 낸다.
 */
export function compareLists(
  left:{cells:Map<string,Cell>;region:GridRegion;keyColumn:number;headerRows:number},
  right:{cells:Map<string,Cell>;region:GridRegion;keyColumn:number;headerRows:number},
):CompareResult{
  const a=readSide(left.cells,left.region,left.keyColumn,left.headerRows)
  const b=readSide(right.cells,right.region,right.keyColumn,right.headerRows)
  const onlyLeft:CompareRow[]=[],onlyRight:CompareRow[]=[]
  let both=0
  for(const row of a.byKey.values()){if(b.byKey.has(row.key))both+=1;else onlyLeft.push(row)}
  for(const row of b.byKey.values())if(!a.byKey.has(row.key))onlyRight.push(row)
  const duplicated=[
    ...[...a.byKey.values()].filter(row=>row.count>1).map(row=>({side:'left' as const,key:row.key,label:row.label,count:row.count})),
    ...[...b.byKey.values()].filter(row=>row.count>1).map(row=>({side:'right' as const,key:row.key,label:row.label,count:row.count})),
  ]
  return {onlyLeft,onlyRight,both,duplicated,blank:{left:a.blank,right:b.blank}}
}

/**
 * "장부!A1:C100" 을 시트 이름과 범위로 나눈다. 느낌표가 없으면 시트 이름이
 * 없는 것으로 보고 undefined 를 낸다 — 부르는 쪽이 지금 시트를 넣는다.
 *
 * 시트 이름에도 느낌표가 들어갈 수 있으므로 **마지막** 느낌표에서 자른다.
 * 앞에서 자르면 "1분기!실적" 이라는 이름의 시트를 영영 못 고른다.
 */
export function splitSheetRange(value:string):{sheetName?:string;region:GridRegion}|undefined{
  const text=value.trim()
  if(text==='')return undefined
  const split=text.lastIndexOf('!')
  const region=parseFilterRange(text.slice(split+1))
  if(!region)return undefined
  if(split<0)return {region}
  // 이름에 빈칸이 있으면 따옴표로 감싸는 것이 스프레드시트의 버릇이다.
  const sheetName=text.slice(0,split).trim().replace(/^'(.*)'$/,'$1')
  return sheetName===''?undefined:{sheetName,region}
}
import { describe,expect,it } from 'vitest'
import { cellKey } from '../state/editor'
import type { Cell } from '../types'
import { compareKey, compareLists, splitSheetRange } from './compareLists'

const cell=(row:number,column:number,value?:unknown):Cell=>({sheet_id:'s',row,column,updated_at:'',...(value===undefined?{}:{value})})
const side=(values:unknown[],headerRows=0)=>({
  cells:new Map(values.map((value,index)=>[cellKey(index+1,1),cell(index+1,1,value)])),
  region:{startRow:1,startColumn:1,endRow:values.length,endColumn:1},
  keyColumn:1,headerRows,
})

describe('compareKey',()=>{
  it('reads a number written as text as the same key',()=>{
    // 은행 내역은 "1,234" 로 오고 장부에는 1234 로 적혀 있다. 글자 그대로
    // 견주면 하나도 맞지 않는다.
    expect(compareKey('1,234')).toBe(compareKey(1234))
    expect(compareKey('₩5,000')).toBe(compareKey(5000))
    expect(compareKey(' 300 ')).toBe(compareKey(300))
  })
  it('ignores surrounding spaces and letter case',()=>{
    expect(compareKey(' ABC ')).toBe(compareKey('abc'))
  })
  it('has no key for a blank cell',()=>{
    expect(compareKey('')).toBeUndefined()
    expect(compareKey(null)).toBeUndefined()
    expect(compareKey('   ')).toBeUndefined()
  })
  it('does not force text that is not a number',()=>{
    expect(compareKey('1,2,3')).toBe('1,2,3')
  })
})

describe('compareLists',()=>{
  it('says what is on one side only',()=>{
    const result=compareLists(side(['가','나','다']),side(['나','다','라']))
    expect(result.onlyLeft.map(row=>row.label)).toEqual(['가'])
    expect(result.onlyRight.map(row=>row.label)).toEqual(['라'])
    expect(result.both).toBe(2)
  })

  it('matches a bank list written as text against a ledger of numbers',()=>{
    const result=compareLists(side(['1,000','2,000','3,000']),side([1000,2000,4000]))
    expect(result.both).toBe(2)
    expect(result.onlyLeft.map(row=>row.label)).toEqual(['3,000'])
    expect(result.onlyRight.map(row=>row.label)).toEqual(['4000'])
  })

  it('reports a key that appears twice instead of hiding it',()=>{
    // 대사에서 같은 번호가 두 번 나오는 것은 발견이지 잡음이 아니다.
    const result=compareLists(side(['가','가','나']),side(['가','나']))
    expect(result.duplicated).toEqual([{side:'left',key:'가',label:'가',count:2}])
    expect(result.both).toBe(2)
  })

  it('counts rows whose key cell is empty rather than dropping them',()=>{
    // 조용히 빼면 "다 맞았다" 는 대사표가 나오고 수는 맞지 않는다.
    const cells=new Map([[cellKey(1,1),cell(1,1,'가')],[cellKey(2,1),cell(2,1,'')],[cellKey(2,2),cell(2,2,'금액만 있음')]])
    const left={cells,region:{startRow:1,startColumn:1,endRow:2,endColumn:2},keyColumn:1,headerRows:0}
    expect(compareLists(left,side(['가'])).blank.left).toBe(1)
  })

  it('skips the header row when told to',()=>{
    const result=compareLists(side(['이름','가'],1),side(['이름','가'],1))
    expect(result.both).toBe(1)
    expect(result.onlyLeft).toEqual([])
  })
})

describe('splitSheetRange',()=>{
  it('splits a sheet name from a range',()=>{
    expect(splitSheetRange('장부!A1:C100')).toEqual({sheetName:'장부',region:{startRow:1,startColumn:1,endRow:100,endColumn:3}})
  })
  it('splits at the last mark so a name may contain one',()=>{
    // "1분기!실적" 이라는 이름의 시트를 앞에서 자르면 영영 못 고른다.
    expect(splitSheetRange('1분기!실적!A1:B2')?.sheetName).toBe('1분기!실적')
  })
  it('unwraps the quotes a name with spaces gets',()=>{
    expect(splitSheetRange("'상반기 장부'!A1:B2")?.sheetName).toBe('상반기 장부')
  })
  it('leaves the sheet unnamed when there is no mark',()=>{
    expect(splitSheetRange('A1:B2')).toEqual({region:{startRow:1,startColumn:1,endRow:2,endColumn:2}})
  })
  it('refuses what is not a range',()=>{
    expect(splitSheetRange('장부!')).toBeUndefined()
    expect(splitSheetRange('장부!A1')).toBeUndefined()
    expect(splitSheetRange('')).toBeUndefined()
    expect(splitSheetRange('!A1:B2')).toBeUndefined()
  })
})

describe('keys that must not be read as numbers',()=>{
  // 대사에서 틀리게 "맞았다" 고 하는 것은 "안 맞았다" 고 하는 것보다 나쁘다.
  // 안 맞으면 사람이 들여다보지만, 맞았다고 하면 거기서 끝난다.
  it('keeps a leading zero apart from the bare number',()=>{
    expect(compareKey('007')).not.toBe(compareKey('7'))
    expect(compareKey('007')).toBe('007')
  })
  it('keeps two long account numbers apart',()=>{
    // 배정밀도로 읽으면 뒤가 뭉개져 둘이 같은 키가 된다.
    expect(compareKey('12345678901234567890')).not.toBe(compareKey('12345678901234567891'))
  })
  it('still matches amounts written with separators',()=>{
    expect(compareKey('1,000')).toBe(compareKey(1000))
    expect(compareKey('0')).toBe(compareKey(0))
    expect(compareKey('0.5')).toBe(compareKey(0.5))
  })
  it('finds the difference two long numbers really have',()=>{
    const result=compareLists(side(['12345678901234567890']),side(['12345678901234567891']))
    expect(result.both).toBe(0)
    expect(result.onlyLeft).toHaveLength(1)
    expect(result.onlyRight).toHaveLength(1)
  })
})

import { useMemo, useState } from 'react'
import { GitCompare } from 'lucide-react'
import { useDialog } from '../lib/useDialog'
import { compareLists, type CompareResult } from '../lib/compareLists'
import type { Cell, Sheet } from '../types'
import type { GridRegion } from '../lib/dataRegion'
import { address } from '../lib/api'
import './CompareDialog.css'

const PREVIEW_ROWS=8

export type CompareSource={sheet:Sheet;region:GridRegion;cells:Map<string,Cell>}

const columnName=(column:number)=>address(1,column).replace(/\d+$/,'')

function KeyColumn({label,region,value,onChange}:{label:string;region:GridRegion;value:number;onChange:(column:number)=>void}){
  const columns=[]
  for(let column=region.startColumn;column<=region.endColumn;column+=1)columns.push(column)
  return <label>{label}
    <select aria-label={label} value={value} onChange={event=>onChange(Number(event.target.value))}>
      {columns.map(column=><option value={column} key={column}>{columnName(column)}열</option>)}
    </select>
  </label>
}

function Bucket({title,rows,empty}:{title:string;rows:Array<{key:string;label:string;row:number}>;empty:string}){
  return <section className="compare-bucket">
    <h3>{title} <b>{rows.length.toLocaleString()}</b></h3>
    {rows.length===0
      ?<p className="compare-empty">{empty}</p>
      :<ul>{rows.slice(0,PREVIEW_ROWS).map(row=><li key={`${row.key}:${row.row}`}><b>{row.row}행</b><code>{row.label||'(빈 값)'}</code></li>)}
        {rows.length>PREVIEW_ROWS&&<li className="compare-more">… 그리고 {(rows.length-PREVIEW_ROWS).toLocaleString()}개 더</li>}</ul>}
  </section>
}

export function CompareDialog({left,right,onClose,onReport}:{
  left:CompareSource;right:CompareSource;onClose:()=>void
  onReport:(result:CompareResult,keys:{left:number;right:number},headerRows:number)=>Promise<void>
}){
  const dialog=useDialog<HTMLElement>(onClose)
  const [headerRows,setHeaderRows]=useState(1)
  const [leftKey,setLeftKey]=useState(left.region.startColumn)
  const [rightKey,setRightKey]=useState(right.region.startColumn)
  const [busy,setBusy]=useState(false)
  const result=useMemo(()=>compareLists(
    {cells:left.cells,region:left.region,keyColumn:leftKey,headerRows},
    {cells:right.cells,region:right.region,keyColumn:rightKey,headerRows},
  ),[left,right,leftKey,rightKey,headerRows])

  const report=async()=>{
    setBusy(true)
    try{await onReport(result,{left:leftKey,right:rightKey},headerRows)}
    finally{setBusy(false)}
  }
  const label=(source:CompareSource)=>`${source.sheet.name}!${address(source.region.startRow,source.region.startColumn)}:${address(source.region.endRow,source.region.endColumn)}`
  const nothing=result.onlyLeft.length===0&&result.onlyRight.length===0

  return <div className="modal-backdrop"><div className="modal compare-modal" role="dialog" ref={dialog as React.RefObject<any>} aria-modal="true" aria-label="두 목록 비교">
    <header><div><GitCompare/><div><h2>두 목록 비교</h2><p>키 열을 맞춰 어느 쪽에만 있는 항목인지 찾습니다.</p></div></div><button aria-label="두 목록 비교 닫기" onClick={onClose}>×</button></header>
    <div className="compare-body">
      <div className="compare-ranges">
        <div><strong>왼쪽</strong><span>{label(left)}</span><KeyColumn label="왼쪽 키 열" region={left.region} value={leftKey} onChange={setLeftKey}/></div>
