	sizeBytes := len(data)
	data = delimited.ToUTF8(data)
	if !utf8.Valid(data) {
		return ParsedWorkbook{}, errors.New("CSV must be UTF-8 encoded")
	}
	delimiter := '\t'
	if format == "csv" {
		delimiter = detectDelimiter(data)
