			break
		}
		if err != nil {
			return ParsedWorkbook{}, fmt.Errorf("parse delimited row %d: %w", rows+1, err)
	// 파일이 스스로 무엇으로 적혔는지 밝히고 오면 그대로 읽는다. 화면은 고른
